// @FIGURE_CODE_BEGIN
var container = document.getElementById('container');
var cvs = document.createElement('canvas');
cvs.style.cssText = 'width:100%;height:100%;display:block';
container.appendChild(cvs);

var BLUE = '#1276a3', RED = '#ee1c25', GRIDC = '#d9d9d9';
var FONT = 'Helvetica, Arial, sans-serif';
var GRID_X = 6, GRID_Y = 5, PADX = 0.72;
var UNIT = 24, FS = 12;

var state = { c: -1, m: 1, showCheck: false };
var geom = {};
var chart = null;

/* ---------- number helpers ---------- */
function gcd(a, b) { a = Math.abs(a); b = Math.abs(b); while (b) { var t = a % b; a = b; b = t; } return a || 1; }
function frac(n, d) { if (d < 0) { n = -n; d = -d; } var g = gcd(n, d); return { n: n / g, d: d / g }; }
function fracStr(f) { return f.d === 1 ? String(f.n) : (f.n + '/' + f.d); }
function fmt(v) { var s = String(Math.round(v * 1000) / 1000); return s.replace('-', '\u2212'); }
function plainNum(v) { return String(Math.round(v * 1000) / 1000); }
function tickStr(i) { return i < 0 ? '\u2212' + (-i) : String(i); }

/* ---------- geometry ---------- */
function clipLine(a, b) {
  var pts = [], y, x, e = 1e-9;
  y = a * (-GRID_X) + b; if (y >= -GRID_Y - e && y <= GRID_Y + e) pts.push([-GRID_X, y]);
  y = a * (GRID_X) + b; if (y >= -GRID_Y - e && y <= GRID_Y + e) pts.push([GRID_X, y]);
  if (Math.abs(a) > 1e-12) {
    x = (GRID_Y - b) / a; if (x >= -GRID_X - e && x <= GRID_X + e) pts.push([x, GRID_Y]);
    x = (-GRID_Y - b) / a; if (x >= -GRID_X - e && x <= GRID_X + e) pts.push([x, -GRID_Y]);
  }
  if (pts.length < 2) return null;
  pts.sort(function (p, q) { return p[0] - q[0]; });
  var p0 = pts[0], p1 = pts[pts.length - 1];
  if (Math.abs(p0[0] - p1[0]) < 1e-9 && Math.abs(p0[1] - p1[1]) < 1e-9) return null;
  return [p0, p1];
}

function computeGeom() {
  var c = state.c, m = state.m;
  geom.blue = { a: -0.5, b: c / 2 }; geom.blue.seg = clipLine(-0.5, c / 2);
  geom.red = { a: m, b: 3 }; geom.red.seg = clipLine(m, 3);
  var det = 1 + 2 * m;
  if (Math.abs(det) < 1e-9) {
    geom.parallel = true; geom.sol = null; geom.onGrid = false;
  } else {
    geom.parallel = false;
    var x = (c - 6) / det, y = m * x + 3;
    geom.sol = { x: x, y: y };
    var cN = Math.round(c * 2), mN = Math.round(m * 10);
    var fx = frac(5 * (cN - 12), 2 * (5 + mN));
    var fy = frac(mN * fx.n + 30 * fx.d, 10 * fx.d);
    geom.fx = fx; geom.fy = fy;
    geom.onGrid = Math.abs(x) <= GRID_X + 1e-9 && Math.abs(y) <= GRID_Y + 1e-9;
  }
  geom.blueEq = 'x + 2y = ' + fmt(c);
  geom.redEq = (Math.abs(m - 1) < 1e-9) ? '\u2212x + y = 3' : ('y = ' + fmt(m) + 'x + 3');
}

/* ---------- drawing helpers ---------- */
function haloText(ctx, s, x, y, align, color, halo) {
  ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
  ctx.lineJoin = 'round'; ctx.miterLimit = 2;
  ctx.strokeStyle = '#fff'; ctx.lineWidth = Math.max(2, halo * 0.3);
  ctx.strokeText(s, x, y);
  ctx.fillStyle = color; ctx.fillText(s, x, y);
