  ctx.font = 'italic ' + Math.round(fs * 1.12) + 'px ' + FONT;
  var bL = null, rL = null;
  if (geom.blue.seg) bL = { p: geom.blue.seg[0], text: geom.blueEq, col: BLUE };
  if (geom.red.seg) rL = { p: geom.red.seg[0], text: geom.redEq, col: RED };
  var byY = bL ? Y(bL.p[1]) - u * 0.42 : null;
  var ryY = rL ? Y(rL.p[1]) - u * 0.42 : null;
  if (byY !== null && ryY !== null && Math.abs(byY - ryY) < fs * 1.9) {
    if (ryY >= byY) ryY = byY + fs * 1.9; else ryY = byY - fs * 1.9;
  }
  function placeEq(L, yy) {
    if (!L) return;
    ctx.font = 'italic ' + Math.round(fs * 1.12) + 'px ' + FONT;
    var w = ctx.measureText(L.text).width;
    var x = X(L.p[0]) - u * 0.55;
    if (x - w < 3) x = w + 3;
    var y = Math.max(fs * 1.4, Math.min(ch.height - fs * 0.6, yy));
    haloText(ctx, L.text, x, y, 'right', L.col, fs);
  }
  placeEq(bL, byY); placeEq(rL, ryY);
  ctx.restore();
}

/* ---------- chart setup ---------- */
function layoutPad() {
  var w = cvs.clientWidth || 600, h = cvs.clientHeight || 400;
  return {
    left: Math.max(46, Math.min(118, w * 0.21)),
    right: Math.max(14, w * 0.035),
    top: Math.max(12, h * 0.04),
    bottom: Math.max(12, h * 0.04)
  };
}
function syncScales() {
  if (!chart) return;
  var pad = layoutPad();
  var w = (cvs.clientWidth || 600) - pad.left - pad.right;
  var h = (cvs.clientHeight || 400) - pad.top - pad.bottom;
  if (w < 30 || h < 30) return;
  var u = Math.min(w / (2 * (GRID_X + PADX)), h / (2 * (GRID_Y + PADX)));
  var hx = w / (2 * u), hy = h / (2 * u);
  chart.options.layout.padding = pad;
  chart.options.scales.x.min = -hx; chart.options.scales.x.max = hx;
  chart.options.scales.y.min = -hy; chart.options.scales.y.max = hy;
  var bw = Math.max(1.6, Math.min(3, u * 0.1));
  chart.data.datasets[0].borderWidth = bw;
  chart.data.datasets[1].borderWidth = bw;
}
function syncData() {
  var b = geom.blue.seg ? geom.blue.seg.map(function (p) { return { x: p[0], y: p[1] }; }) : [];
  var r = geom.red.seg ? geom.red.seg.map(function (p) { return { x: p[0], y: p[1] }; }) : [];
  chart.data.datasets[0].data = b;
  chart.data.datasets[1].data = r;
}
function updateStatus() {
  var el = document.getElementById('statusCap');
  if (!el) return;
  if (geom.parallel) { el.textContent = 'No solution \u2014 parallel lines'; el.style.color = '#a3212a'; }
  else if (!geom.onGrid) { el.textContent = 'Solution off-grid: (' + fracStr(geom.fx) + ', ' + fracStr(geom.fy) + ')'; el.style.color = '#8a5a00'; }
  else { el.textContent = 'One solution: (' + fracStr(geom.fx) + ', ' + fracStr(geom.fy) + ')'; el.style.color = '#1f4f66'; }
}
function refresh() {
  computeGeom(); syncScales(); syncData(); updateStatus();
  chart.update('none');
}

computeGeom();
chart = new Chart(cvs.getContext('2d'), {
  type: 'scatter',
  data: {
    datasets: [
      { label: 'blue', data: [], showLine: true, borderColor: BLUE, borderWidth: 2.4, pointRadius: 0, fill: false, tension: 0 },
      { label: 'red', data: [], showLine: true, borderColor: RED, borderWidth: 2.4, pointRadius: 0, fill: false, tension: 0 }
    ]
  },
  options: {
    responsive: true, maintainAspectRatio: false, animation: false, events: [],
    layout: { padding: layoutPad() },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: { type: 'linear', min: -6.8, max: 6.8, grid: { display: false }, border: { display: false }, ticks: { display: false } },
      y: { type: 'linear', min: -5.8, max: 5.8, grid: { display: false }, border: { display: false }, ticks: { display: false } }
    }
  },
  plugins: [figPlugin]
});
window.__markRendered();
syncScales(); syncData(); updateStatus(); chart.update('none');
requestAnimationFrame(function () { syncScales(); chart.update('none'); });

document.addEventListener('fig-resize', function () {
  requestAnimationFrame(function () { syncScales(); chart.update('none'); });
});

/* ---------- interaction ---------- */
function cpos(e) { var r = cvs.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; }
function segDist(p, a, b) {
  var vx = b.x - a.x, vy = b.y - a.y, wx = p.x - a.x, wy = p.y - a.y;
  var L = vx * vx + vy * vy; if (L < 1e-9) return Math.hypot(wx, wy);
  var t = Math.max(0, Math.min(1, (wx * vx + wy * vy) / L));
  return Math.hypot(wx - t * vx, wy - t * vy);
}
function segPx(seg) {
  if (!seg) return null;
  var sx = chart.scales.x, sy = chart.scales.y;
  return [{ x: sx.getPixelForValue(seg[0][0]), y: sy.getPixelForValue(seg[0][1]) },
  { x: sx.getPixelForValue(seg[1][0]), y: sy.getPixelForValue(seg[1][1]) }];
}
function hitTest(p) {
  if (geom._dotPx) {
    var d = Math.hypot(p.x - geom._dotPx.x, p.y - geom._dotPx.y);
    if (d < Math.max(9, geom._dotPx.r * 2.6)) {
      return { kind: 'dot', tip: 'Solution (' + fracStr(geom.fx) + ', ' + fracStr(geom.fy) + ') \u2014 lies on BOTH lines. Click to verify.' };
    }
  }
  var bs = segPx(geom.blue.seg), rs = segPx(geom.red.seg);
  var tol = Math.max(6, UNIT * 0.24);
  if (bs && segDist(p, bs[0], bs[1]) < tol) return { kind: 'blue', tip: 'Blue line: ' + geom.blueEq.replace('\u2212', '-') };
  if (rs && segDist(p, rs[0], rs[1]) < tol) return { kind: 'red', tip: 'Red line: ' + geom.redEq.replace('\u2212', '-') };
  return null;
}
cvs.addEventListener('mousemove', function (e) {
  var h = hitTest(cpos(e));
  cvs.style.cursor = h ? 'pointer' : 'default';
  if (h) showTooltip(h.tip, e); else hideTooltip();
});
cvs.addEventListener('mouseleave', hideTooltip);
cvs.addEventListener('click', function (e) {
  var h = hitTest(cpos(e));
  if (!h) return;
  if (h.kind === 'dot') { state.showCheck = true; refresh(); popupCheck(); }
  else if (h.kind === 'blue') {
    showPopup('The blue line', 'Every point on this line satisfies x + 2y = ' + plainNum(state.c) + '. Taken alone, that one equation has infinitely many solutions \u2014 one ordered pair for each point of the line.');
  } else {
    showPopup('The red line', 'Every point on this line satisfies ' + geom.redEq.replace('\u2212', '-') + '. A system asks which ordered pair works for this line AND the blue line at the same time \u2014 that is the crossing point.');
  }
});

function popupCheck() {
  if (geom.parallel) {
    showPopup('No solution', 'The red line now has slope \u22121/2, exactly the blue line\u2019s slope, so the two lines are parallel and never meet. No ordered pair can satisfy both equations, so the system has no solution.');
    return;
  }
  var xs = fracStr(geom.fx), ys = fracStr(geom.fy);
  var body = 'Substituting the point (' + xs + ', ' + ys + ') into both equations:\n\n' +
    'Blue:  x + 2y = (' + xs + ') + 2(' + ys + ') = ' + plainNum(state.c) + '  \u2713\n' +
    'Red:   y = ' + plainNum(state.m) + 'x + 3 \u2192 ' + ys + ' = ' + plainNum(state.m) + '(' + xs + ') + 3  \u2713\n\n' +
    'Both statements are true for the same ordered pair, which is exactly what it means to be the solution of the system.';
  showPopup('Checking the solution', body);
}

/* ---------- controls ---------- */
function update_blueIntercept(v) { state.c = v; refresh(); }
function update_redSlope(v) { state.m = v; refresh(); }
function trigger_checkSolution() {
  state.showCheck = !state.showCheck;
  refresh();
  if (state.showCheck) popupCheck(); else hidePopup();
}

/* ---------- demo player ---------- */
var STEPS = [
  { title: 'The original system', narration: 'Two lines are drawn on one grid: blue x + 2y = \u22121 falling to the right, red \u2212x + y = 3 rising to the right. They cross exactly once, in the second quadrant.', state: { blueIntercept: -1, redSlope: 1, showCheck: false } },
  { title: 'Read the solution', narration: 'Click the black dot: dashed guides drop to the axes at x = \u22127/3 and y = 2/3, and both equations check out when those values are substituted.', state: { blueIntercept: -1, redSlope: 1, showCheck: true } },
  { title: 'Slide the blue line', narration: 'Change the constant to c = 3 and the blue line shifts up; the crossing point slides along the red line to a new place, but there is still exactly one solution.', state: { blueIntercept: 3, redSlope: 1, showCheck: true } },
  { title: 'Rotate the red line', narration: 'Flatten the red line\u2019s slope toward \u22120.4 and the intersection races away to the left, off the visible grid \u2014 the solution still exists but is far from the origin.', state: { blueIntercept: -1, redSlope: -0.4, showCheck: false } },
  { title: 'Parallel: no solution', narration: 'At slope exactly \u22120.5 the red line is parallel to the blue line. The lines never meet, so the system has no solution at all.', state: { blueIntercept: -1, redSlope: -0.5, showCheck: false } },
  { title: 'Back to one crossing', narration: 'Tilt the red line back to a positive slope and a single crossing reappears \u2014 orientation, not position, decides whether a solution exists.', state: { blueIntercept: -1, redSlope: 1, showCheck: false } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  var s = STEPS[stepIdx];
  var bi = document.getElementById('blueInterceptInput'), rs = document.getElementById('redSlopeInput');
  bi.value = s.state.blueIntercept; document.getElementById('blueInterceptVal').value = s.state.blueIntercept;
  rs.value = s.state.redSlope; document.getElementById('redSlopeVal').value = s.state.redSlope;
  state.c = +s.state.blueIntercept; state.m = +s.state.redSlope; state.showCheck = !!s.state.showCheck;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + STEPS.length + ' \u00b7 ' + s.title;
  refresh();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }
applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: Graphing two linear equations on shared axes turns an algebraic system into a picture: the single point where the lines cross is the ordered pair that satisfies both equations at once.
KEY INSIGHT (what students should walk away understanding): A solution to a system is not a number but a point: the one ordered pair that lies on both lines simultaneously — and if the lines are parallel, no such point exists.
DEMO STEPS: 6 guided steps — implement the step player in #ui

