  arrow(ctx, axv, ay1, 0, -1, ah, '#000'); arrow(ctx, axv, ay0, 0, 1, ah, '#000');

  /* ticks + tick labels — styles reset every iteration (halo strokes reuse ctx) */
  var tl = Math.max(2.5, u * 0.14);
  var maxYLabW = 0;
  ctx.font = Math.round(fs) + 'px ' + FONT;
  for (i = -GRID_X; i <= GRID_X; i++) {
    if (!i) continue;
    ctx.setLineDash([]); ctx.strokeStyle = '#000'; ctx.lineWidth = Math.max(1.2, lw * 0.75);
    var tx = Math.round(X(i)) + 0.5;
    ctx.beginPath(); ctx.moveTo(tx, ay - tl); ctx.lineTo(tx, ay + tl); ctx.stroke();
    ctx.font = Math.round(fs) + 'px ' + FONT;
    haloText(ctx, tickStr(i), X(i), ay + tl + fs * 1.1, 'center', '#111', fs);
  }
  for (j = -GRID_Y; j <= GRID_Y; j++) {
    if (!j) continue;
    ctx.setLineDash([]); ctx.strokeStyle = '#000'; ctx.lineWidth = Math.max(1.2, lw * 0.75);
    var ty = Math.round(Y(j)) + 0.5;
    ctx.beginPath(); ctx.moveTo(axv - tl, ty); ctx.lineTo(axv + tl, ty); ctx.stroke();
    ctx.font = Math.round(fs) + 'px ' + FONT;
    maxYLabW = Math.max(maxYLabW, ctx.measureText(tickStr(j)).width);
    haloText(ctx, tickStr(j), axv - tl - fs * 0.35, Y(j) + fs * 0.36, 'right', '#111', fs);
  }

  ctx.font = 'italic ' + Math.round(fs * 1.35) + 'px ' + FONT;
  haloText(ctx, 'x', ax1 + fs * 0.9, ay + fs * 0.48, 'center', '#000', fs * 1.2);
  haloText(ctx, 'y', axv + fs * 0.15, ay1 - fs * 0.9, 'center', '#000', fs * 1.2);

  geom._ax = { ay: ay, axv: axv, tl: tl, yLabW: maxYLabW, fs: fs, u: u };
  ctx.restore();
}

function drawFront(ch) {
  var ctx = ch.ctx, sx = ch.scales.x, sy = ch.scales.y;
  var X = function (v) { return sx.getPixelForValue(v); };
  var Y = function (v) { return sy.getPixelForValue(v); };
  var A = geom._ax || { ay: Y(0), axv: X(0), tl: 4, yLabW: 10, fs: FS, u: UNIT };
  var u = UNIT, fs = FS, ay = A.ay, axv = A.axv, tl = A.tl;
  ctx.save();

  /* arrowheads on both line ends */
  var pairs = [[geom.blue, BLUE], [geom.red, RED]];
  for (var k = 0; k < pairs.length; k++) {
    var seg = pairs[k][0].seg; if (!seg) continue;
    var ax = X(seg[0][0]), ayy = Y(seg[0][1]), bx = X(seg[1][0]), by = Y(seg[1][1]);
    var s = Math.max(5, u * 0.34);
    arrow(ctx, ax, ayy, ax - bx, ayy - by, s, pairs[k][1]);
    arrow(ctx, bx, by, bx - ax, by - ayy, s, pairs[k][1]);
  }

  /* forbidden zones for floating labels */
  var avoid = [
    { x0: axv - (A.yLabW + tl + fs * 0.7), y0: 0, x1: axv + tl + fs * 0.5, y1: ch.height },
    { x0: 0, y0: ay - tl - fs * 0.4, x1: ch.width, y1: ay + tl + fs * 1.8 }
  ];
  var segsPx = [];
  if (geom.blue.seg) segsPx.push([{ x: X(geom.blue.seg[0][0]), y: Y(geom.blue.seg[0][1]) }, { x: X(geom.blue.seg[1][0]), y: Y(geom.blue.seg[1][1]) }]);
  if (geom.red.seg) segsPx.push([{ x: X(geom.red.seg[0][0]), y: Y(geom.red.seg[0][1]) }, { x: X(geom.red.seg[1][0]), y: Y(geom.red.seg[1][1]) }]);

  /* dashed guides + axis readouts */
  if (state.showCheck && geom.sol && geom.onGrid) {
    var dx = X(geom.sol.x), dy = Y(geom.sol.y);
    ctx.save();
    ctx.strokeStyle = '#555'; ctx.lineWidth = Math.max(1, u * 0.05); ctx.setLineDash([4, 3]);
    ctx.beginPath(); ctx.moveTo(dx, dy); ctx.lineTo(dx, ay); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(dx, dy); ctx.lineTo(axv, dy); ctx.stroke();
    ctx.restore();

    var xt = tokensFor(geom.fx), yt = tokensFor(geom.fy);
    var rfs = fs * 0.95;
    var wx = measureTokens(ctx, xt, rfs);
    var xrx = Math.max(3, Math.min(ch.width - wx - 3, dx - wx / 2));
    var xry = ay + tl + fs * 3.0;
    drawTokens(ctx, xt, xrx, xry, rfs, '#333', true);
    avoid.push({ x0: xrx - fs * 0.3, y0: xry - fs * 1.2, x1: xrx + wx + fs * 0.3, y1: xry + fs * 1.2 });

    var wy = measureTokens(ctx, yt, rfs);
    var yrx = Math.max(3, axv - A.yLabW - tl - fs * 1.6 - wy);
    var yry = dy - fs * 0.1;
    drawTokens(ctx, yt, yrx, yry, rfs, '#333', true);
    avoid.push({ x0: yrx - fs * 0.3, y0: yry - fs * 1.2, x1: yrx + wy + fs * 0.3, y1: yry + fs * 1.2 });
  }

  /* intersection dot + coordinate label */
  if (geom.sol && geom.onGrid) {
    var px = X(geom.sol.x), py = Y(geom.sol.y);
    var r = Math.max(2.6, Math.min(6, u * 0.16));
    ctx.setLineDash([]);
    ctx.beginPath(); ctx.arc(px, py, r, 0, Math.PI * 2);
    ctx.fillStyle = '#000'; ctx.fill();
    ctx.lineWidth = Math.max(1, r * 0.4); ctx.strokeStyle = '#fff'; ctx.stroke();
    geom._dotPx = { x: px, y: py, r: r };

    var toks = coordTokens(geom.fx, geom.fy);
    var w = measureTokens(ctx, toks, fs);
    var best = placeCoordLabel(ctx, ch, w, fs, px, py, avoid, segsPx);

    /* leader line when the label had to move away from the dot */
    var lcx = best.x + w / 2, lcy = best.cy;
    var dist = Math.hypot(lcx - px, lcy - py);
    if (dist > u * 2.4) {
      var ux = (px - lcx) / dist, uy = (py - lcy) / dist;
      ctx.save(); ctx.setLineDash([]); ctx.strokeStyle = '#9a9a9a'; ctx.lineWidth = Math.max(0.8, u * 0.035);
      ctx.beginPath();
      ctx.moveTo(lcx + ux * (fs * 1.25), lcy + uy * (fs * 1.25));
      ctx.lineTo(px - ux * (r + 2), py - uy * (r + 2));
      ctx.stroke(); ctx.restore();
    }
    drawTokens(ctx, toks, best.x, best.cy, fs, '#000', true);
  } else {
    geom._dotPx = null;
  }

  /* off-grid pointer */
  if (geom.sol && !geom.onGrid) {
    var t = 1;
    if (Math.abs(geom.sol.x) > GRID_X) t = Math.min(t, GRID_X / Math.abs(geom.sol.x));
    if (Math.abs(geom.sol.y) > GRID_Y) t = Math.min(t, GRID_Y / Math.abs(geom.sol.y));
    var ex = geom.sol.x * t * 0.97, ey = geom.sol.y * t * 0.97;
    arrow(ctx, X(ex), Y(ey), X(geom.sol.x) - X(0), Y(geom.sol.y) - Y(0), Math.max(6, u * 0.45), '#555');
  }

  /* on-canvas caption only for the special cases */
  var cap = null;
  if (geom.parallel) cap = 'No solution \u2014 parallel lines';
  else if (!geom.onGrid) cap = 'Solution off-grid: (' + fracStr(geom.fx).replace('-', '\u2212') + ', ' + fracStr(geom.fy).replace('-', '\u2212') + ')';
  if (cap) {
    ctx.font = Math.round(fs * 1.05) + 'px ' + FONT;
    var cw = ctx.measureText(cap).width;
    var cx0 = Math.max(4, X(-GRID_X) + fs * 0.4), cy0 = Math.max(2, Y(GRID_Y) - fs * 2.6);
    ctx.save(); ctx.setLineDash([]);
    ctx.fillStyle = 'rgba(255,255,255,0.9)';
    ctx.fillRect(cx0 - 4, cy0 - 2, cw + 8, fs * 1.6);
    ctx.restore();
    haloText(ctx, cap, cx0, cy0 + fs * 1.1, 'left', '#333', fs);
  }

  /* equation labels at the outer ends of each line */
  var bL = geom.blue.seg ? { p: geom.blue.seg[0], text: geom.blueEq, col: BLUE } : null;
  var rL = geom.red.seg ? { p: geom.red.seg[0], text: geom.redEq, col: RED } : null;
  var byY = bL ? Y(bL.p[1]) - u * 0.45 : null;
  var ryY = rL ? Y(rL.p[1]) - u * 0.45 : null;
  if (byY !== null && ryY !== null && Math.abs(byY - ryY) < fs * 2.0) {
    if (ryY >= byY) ryY = byY + fs * 2.0; else ryY = byY - fs * 2.0;
  }
  function placeEq(L, yy) {
    if (!L) return;
    ctx.font = 'italic ' + Math.round(fs * 1.12) + 'px ' + FONT;
    var w2 = ctx.measureText(L.text).width;
    var x = X(L.p[0]) - u * 0.6;
    if (x - w2 < 3) x = w2 + 3;
    var y = Math.max(fs * 1.5, Math.min(ch.height - fs * 0.7, yy));
    haloText(ctx, L.text, x, y, 'right', L.col, fs);
  }
  placeEq(bL, byY); placeEq(rL, ryY);
  ctx.restore();
}

function placeCoordLabel(ctx, ch, w, fs, px, py, avoid, segs) {
  var u = UNIT;
  var cands = [
    [px - w + u * 0.6, py - u * 1.8],
    [px - w * 0.5, py - u * 1.85],
    [px + u * 0.5, py - u * 1.5],
    [px - w - u * 0.5, py - u * 1.3],
    [px - w + u * 0.6, py - u * 3.1],
    [px - w * 0.5, py + u * 1.9],
    [px + u * 0.5, py + u * 1.5]
  ];
  var best = null;
  for (var i = 0; i < cands.length; i++) {
    var x = Math.max(3, Math.min(ch.width - w - 3, cands[i][0]));
    var cy = Math.max(fs * 1.35, Math.min(ch.height - fs * 1.35, cands[i][1]));
    var r = { x0: x - fs * 0.3, y0: cy - fs * 1.15, x1: x + w + fs * 0.3, y1: cy + fs * 1.15 };
    var pen = i * 0.35;
    for (var j = 0; j < avoid.length; j++) pen += rectOverlap(r, avoid[j]) / (fs * fs) * 5;
    for (var k = 0; k < segs.length; k++) if (segInRect(segs[k][0], segs[k][1], r)) pen += 55;
    pen += Math.hypot(x + w / 2 - px, cy - py) / u * 1.1;
    if (!best || pen < best.pen) best = { x: x, cy: cy, pen: pen };
  }
  return best;
}

/* ---------- chart setup ---------- */
function layoutPad() {
  var w = cvs.clientWidth || 600, h = cvs.clientHeight || 400;
  return {
    left: Math.max(42, Math.min(112, w * 0.18)),
    right: Math.max(16, Math.min(46, w * 0.05)),
    top: Math.max(12, h * 0.045),
    bottom: Math.max(14, h * 0.05)
  };
}
function syncScales() {
  if (!chart) return;
  var pad = layoutPad();
  var w = (cvs.clientWidth || 600) - pad.left - pad.right;
  var h = (cvs.clientHeight || 400) - pad.top - pad.bottom;
  if (w < 30 || h < 30) return;
  var u = Math.min(w / (2 * (GRID_X + PADX)), h / (2 * (GRID_Y + PADX)));
  var hx = w / (2 * u), hy = h / (2 * u);
  chart.options.layout.padding = pad;
  chart.options.scales.x.min = -hx; chart.options.scales.x.max = hx;
  chart.options.scales.y.min = -hy; chart.options.scales.y.max = hy;
  var bw = Math.max(1.6, Math.min(3, u * 0.1));
  chart.data.datasets[0].borderWidth = bw;
  chart.data.datasets[1].borderWidth = bw;
}
function syncData() {
  var b = geom.blue.seg ? geom.blue.seg.map(function (p) { return { x: p[0], y: p[1] }; }) : [];
  var r = geom.red.seg ? geom.red.seg.map(function (p) { return { x: p[0], y: p[1] }; }) : [];
  chart.data.datasets[0].data = b;
  chart.data.datasets[1].data = r;
}
function updateStatus() {
  var el = document.getElementById('statusCap');
  if (!el) return;
  if (geom.parallel) { el.textContent = 'No solution \u2014 parallel lines'; el.style.color = '#a3212a'; }
  else if (!geom.onGrid) { el.textContent = 'Solution off-grid: (' + fracStr(geom.fx) + ', ' + fracStr(geom.fy) + ')'; el.style.color = '#8a5a00'; }
  else { el.textContent = 'One solution: (' + fracStr(geom.fx) + ', ' + fracStr(geom.fy) + ')'; el.style.color = '#1f4f66'; }
}
function refresh() {
  computeGeom(); syncScales(); syncData(); updateStatus();
  chart.update('none');
}

computeGeom();
chart = new Chart(cvs.getContext('2d'), {
  type: 'scatter',
  data: {
    datasets: [
      { label: 'blue', data: [], showLine: true, borderColor: BLUE, borderWidth: 2.4, pointRadius: 0, fill: false, tension: 0 },
      { label: 'red', data: [], showLine: true, borderColor: RED, borderWidth: 2.4, pointRadius: 0, fill: false, tension: 0 }
    ]
  },
  options: {
    responsive: true, maintainAspectRatio: false, animation: false, events: [],
    layout: { padding: layoutPad() },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: { type: 'linear', min: -6.8, max: 6.8, grid: { display: false }, border: { display: false }, ticks: { display: false } },
      y: { type: 'linear', min: -5.8, max: 5.8, grid: { display: false }, border: { display: false }, ticks: { display: false } }
    }
  },
  plugins: [figPlugin]
});
window.__markRendered();
syncScales(); syncData(); updateStatus(); chart.update('none');
requestAnimationFrame(function () { syncScales(); chart.update('none'); });

document.addEventListener('fig-resize', function () {
  requestAnimationFrame(function () { syncScales(); chart.update('none'); });
});

/* ---------- interaction ---------- */
function cpos(e) { var r = cvs.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; }
function segDist(p, a, b) {
  var vx = b.x - a.x, vy = b.y - a.y, wx = p.x - a.x, wy = p.y - a.y;
  var L = vx * vx + vy * vy; if (L < 1e-9) return Math.hypot(wx, wy);
  var t = Math.max(0, Math.min(1, (wx * vx + wy * vy) / L));
  return Math.hypot(wx - t * vx, wy - t * vy);
}
function segPx(seg) {
  if (!seg) return null;
  var sx = chart.scales.x, sy = chart.scales.y;
  return [{ x: sx.getPixelForValue(seg[0][0]), y: sy.getPixelForValue(seg[0][1]) },
  { x: sx.getPixelForValue(seg[1][0]), y: sy.getPixelForValue(seg[1][1]) }];
}
function hitTest(p) {
  if (geom._dotPx) {
    var d = Math.hypot(p.x - geom._dotPx.x, p.y - geom._dotPx.y);
    if (d < Math.max(9, geom._dotPx.r * 2.6)) {
      return { kind: 'dot', tip: 'Solution (' + fracStr(geom.fx) + ', ' + fracStr(geom.fy) + ') \u2014 lies on BOTH lines. Click to verify.' };
    }
  }
  var bs = segPx(geom.blue.seg), rs = segPx(geom.red.seg);
  var tol = Math.max(6, UNIT * 0.24);
  if (bs && segDist(p, bs[0], bs[1]) < tol) return { kind: 'blue', tip: 'Blue line: ' + geom.blueEq.replace('\u2212', '-') };
  if (rs && segDist(p, rs[0], rs[1]) < tol) return { kind: 'red', tip: 'Red line: ' + geom.redEq.replace('\u2212', '-') };
  return null;
}
cvs.addEventListener('mousemove', function (e) {
  var h = hitTest(cpos(e));
  cvs.style.cursor = h ? 'pointer' : 'default';
  if (h) showTooltip(h.tip, e); else hideTooltip();
});
cvs.addEventListener('mouseleave', hideTooltip);
cvs.addEventListener('click', function (e) {
  var h = hitTest(cpos(e));
  if (!h) return;
  if (h.kind === 'dot') { state.showCheck = true; refresh(); popupCheck(); }
  else if (h.kind === 'blue') {
    showPopup('The blue line', 'Every point on this line satisfies x + 2y = ' + plainNum(state.c) + '. Taken alone, that one equation has infinitely many solutions \u2014 one ordered pair for each point of the line.');
  } else {
    showPopup('The red line', 'Every point on this line satisfies ' + geom.redEq.replace('\u2212', '-') + '. A system asks which ordered pair works for this line AND the blue line at the same time \u2014 that is the crossing point.');
  }
});

function popupCheck() {
  if (geom.parallel) {
    showPopup('No solution', 'The red line now has slope \u22121/2, exactly the blue line\u2019s slope, so the two lines are parallel and never meet. No ordered pair can satisfy both equations, so the system has no solution.');
    return;
  }
  var xs = fracStr(geom.fx), ys = fracStr(geom.fy);
  var body = 'Substituting the point (' + xs + ', ' + ys + ') into both equations:\n\n' +
    'Blue:  x + 2y = (' + xs + ') + 2(' + ys + ') = ' + plainNum(state.c) + '  \u2713\n' +
    'Red:   y = ' + plainNum(state.m) + 'x + 3 \u2192 ' + ys + ' = ' + plainNum(state.m) + '(' + xs + ') + 3  \u2713\n\n' +
    'Both statements are true for the same ordered pair, which is exactly what it means to be the solution of the system.';
  showPopup('Checking the solution', body);
}

/* ---------- controls ---------- */
function update_blueIntercept(v) { state.c = v; refresh(); }
function update_redSlope(v) { state.m = v; refresh(); }
function trigger_checkSolution() {
  state.showCheck = !state.showCheck;
  refresh();
  if (state.showCheck) popupCheck(); else hidePopup();
}

/* ---------- demo player ---------- */
var STEPS = [
  { title: 'The original system', narration: 'Two lines are drawn on one grid: blue x + 2y = \u22121 falling to the right, red \u2212x + y = 3 rising to the right. They cross exactly once, in the second quadrant.', state: { blueIntercept: -1, redSlope: 1, showCheck: false } },
  { title: 'Read the solution', narration: 'Click the black dot: dashed guides drop to the axes at x = \u22127/3 and y = 2/3, and both equations check out when those values are substituted.', state: { blueIntercept: -1, redSlope: 1, showCheck: true } },
  { title: 'Slide the blue line', narration: 'Change the constant to c = 3 and the blue line shifts up; the crossing point slides along the red line to a new place, but there is still exactly one solution.', state: { blueIntercept: 3, redSlope: 1, showCheck: true } },
  { title: 'Rotate the red line', narration: 'Flatten the red line\u2019s slope toward \u22120.4 and the intersection races away to the left, off the visible grid \u2014 the solution still exists but is far from the origin.', state: { blueIntercept: -1, redSlope: -0.4, showCheck: false } },
  { title: 'Parallel: no solution', narration: 'At slope exactly \u22120.5 the red line is parallel to the blue line. The lines never meet, so the system has no solution at all.', state: { blueIntercept: -1, redSlope: -0.5, showCheck: false } },
  { title: 'Back to one crossing', narration: 'Tilt the red line back to a positive slope and a single crossing reappears \u2014 orientation, not position, decides whether a solution exists.', state: { blueIntercept: -1, redSlope: 1, showCheck: false } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  var s = STEPS[stepIdx];
  var bi = document.getElementById('blueInterceptInput'), rs = document.getElementById('redSlopeInput');
  bi.value = s.state.blueIntercept; document.getElementById('blueInterceptVal').value = s.state.blueIntercept;
  rs.value = s.state.redSlope; document.getElementById('redSlopeVal').value = s.state.redSlope;
  state.c = +s.state.blueIntercept; state.m = +s.state.redSlope; state.showCheck = !!s.state.showCheck;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + STEPS.length + ' \u00b7 ' + s.title;
  refresh();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }
applyStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: Graphing two linear equations on shared axes turns an algebraic system into a picture: the single point where the lines cross is the ordered pair that satisfies both equations at once.
KEY INSIGHT (what students should walk away understanding): A solution to a system is not a number but a point: the one ordered pair that lies on both lines simultaneously — and if the lines are parallel, no such point exists.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Graphing two linear equations on shared axes turns an algebraic system into a picture: the single point where the lines cross is the ordered pair that satisfies both equations at once.",
  "figureType": "line_plot",
  "elements": [
    "Dotted square coordinate grid spanning x from -6 to 6 and y from -5 to 5, one unit per cell",
    "Horizontal x-axis, black, with arrowheads at both ends and integer tick labels -6 through 6",
    "Vertical y-axis, black, with arrowheads at both ends and integer tick labels -5 through 5",
    "Axis names: italic 'x' at the right end of the horizontal axis, italic 'y' at the top of the vertical axis",
    "Blue line of negative slope (slope -1/2) crossing the y-axis just below the origin at -1/2, entering upper-left and exiting lower-right, arrowheads at both ends",
    "Blue equation label at the far left of the blue line reading 'x + 2y = -1'",
    "Red line of positive slope (slope 1) crossing the y-axis at 3, rising from lower-left to upper-right, arrowheads at both ends",
    "Red equation label at the lower left reading '-x + y = 3'",
    "Filled black dot at the intersection in the second quadrant, just left of the y-axis and slightly above the x-axis",
    "Stacked-fraction coordinate annotation above the dot reading (-7/3, 2/3)",
    "Dashed black guide segments (appear on click) dropping from the intersection dot to the x-axis and across to the y-axis",
    "Substitution check panel (appears on click) showing each equation with the dot's coordinates substituted and both sides evaluated",
    "Status caption reporting 'one solution' / 'no solution — parallel lines' / 'solution off-grid'"
  ],
  "interactions": [
    {
      "id": "blueIntercept",
      "type": "slider",
      "label": "Blue line constant c in x + 2y = c",
      "range": [
        -8,
        8,
        0.5
      ],
      "default": -1,
      "teaches": "Shifting one line up or down slides the crossing point along the other line — the solution is a location determined jointly by both equations, not by either alone."
    },
    {
      "id": "redSlope",
      "type": "slider",
      "label": "Red line slope m in y = m·x + 3",
      "range": [
        -2,
        2,
        0.1
      ],
      "default": 1,
      "teaches": "Rotating a line about its y-intercept moves the crossing point, and when its slope matches the blue line's -1/2 the lines are parallel and the system has no solution."
    },
    {
      "id": "checkSolution",
      "type": "click",
      "teaches": "Selecting the intersection dot substitutes its coordinates into both equations at once, showing the same ordered pair makes both statements true."
    }
  ],
  "demo_steps": [
