    [px + u * 0.28, py - u * 1.65],
    [px + u * 0.45, py - u * 3.95],
    [px - w * 0.5, py - u * 2.4],
    [px - w - u * 0.4, py - u * 1.7],
    [px + u * 0.4, py + u * 1.8],
    [px - w - u * 0.4, py + u * 1.7],
